'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { ChevronDown, Plus, Minus } from 'lucide-react';

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
        maximumFractionDigits: 0,
    }).format(amount);
};

const EMIcalculator = () => {
    // State
    const [loanAmount, setLoanAmount] = useState<number>(5000000);
    const [tenureYears, setTenureYears] = useState<number>(10);
    const [interestRate, setInterestRate] = useState<number>(9);
    const [processingFeePercent, setProcessingFeePercent] = useState<number>(0.5); // Default assumed 0.5% or static value

    // Results
    const [emi, setEmi] = useState<number>(0);
    const [totalInterest, setTotalInterest] = useState<number>(0);
    const [totalPayment, setTotalPayment] = useState<number>(0);
    const [chartData, setChartData] = useState<{ label: string, value: number, color: string }[]>([]);

    // Schedule
    const [amortizationSchedule, setAmortizationSchedule] = useState<any[]>([]);

    useEffect(() => {
        calculateEMI();
    }, [loanAmount, tenureYears, interestRate]);

    const calculateEMI = () => {
        const P = loanAmount;
        const R = interestRate / 12 / 100;
        const N = tenureYears * 12;

        if (P === 0 || R === 0 || N === 0) return;

        // EMI Formula
        const emiValue = (P * R * Math.pow(1 + R, N)) / (Math.pow(1 + R, N) - 1);
        const totalPayable = emiValue * N;
        const totalInt = totalPayable - P;

        setEmi(Math.round(emiValue));
        setTotalPayment(Math.round(totalPayable));
        setTotalInterest(Math.round(totalInt));

        setChartData([
            { label: 'Principal', value: P, color: '#191758' }, // Gold (Loan Amount)
            { label: 'Interest', value: Math.round(totalInt), color: '#B88746 ' }, // Dark Blue (Interest)
        ]);

        // Generate Amortization Schedule (Yearly)
        let balance = P;
        let schedule = [];
        let yearlyInterest = 0;
        let yearlyPrincipal = 0;
        let currentYear = new Date().getFullYear() + 1; // Start from next year for projection

        for (let m = 1; m <= N; m++) {
            const interestComp = balance * R;
            const principalComp = emiValue - interestComp;
            balance -= principalComp;

            yearlyInterest += interestComp;
            yearlyPrincipal += principalComp;

            if (m % 12 === 0 || m === N) {
                const totalPaidSoFar = P + totalInt - (balance > 0 ? balance + (balance * R * (N - m)) : 0); // Approx
                // Simplified paid percentage
                const paidPercent = Math.min(100, Math.round(((P - balance) / P) * 100 * 100) / 100);

                schedule.push({
                    year: currentYear,
                    principal: Math.round(yearlyPrincipal),
                    interest: Math.round(yearlyInterest),
                    balance: Math.max(0, Math.round(balance)),
                    paidPercent: paidPercent.toFixed(2)
                });

                yearlyInterest = 0;
                yearlyPrincipal = 0;
                currentYear++;
            }
        }
        setAmortizationSchedule(schedule);
    };

    // Simple SVG Pie Chart Component
    const PieChart = ({ data }: { data: { value: number, color: string }[] }) => {
        const total = data.reduce((acc, item) => acc + item.value, 0);
        let cumulativePercent = 0;

        const getCoordinatesForPercent = (percent: number) => {
            const x = Math.cos(2 * Math.PI * percent);
            const y = Math.sin(2 * Math.PI * percent);
            return [x, y];
        };

        return (
            <div className="relative w-64 h-64 md:w-72 md:h-72 mx-auto">
                <svg viewBox="-1 -1 2 2" className="transform -rotate-90 w-full h-full">
                    {data.map((slice, i) => {
                        const startPercent = cumulativePercent;
                        const slicePercent = slice.value / total;
                        cumulativePercent += slicePercent;
                        const endPercent = cumulativePercent;

                        const [startX, startY] = getCoordinatesForPercent(startPercent);
                        const [endX, endY] = getCoordinatesForPercent(endPercent);

                        // If slice is 100%, draw a circle
                        if (slicePercent === 1) {
                            return <circle key={i} cx="0" cy="0" r="1" fill={slice.color} />;
                        }

                        const largeArcFlag = slicePercent > 0.5 ? 1 : 0;
                        const pathData = `M 0 0 L ${startX} ${startY} A 1 1 0 ${largeArcFlag} 1 ${endX} ${endY} L 0 0`;

                        return <path key={i} d={pathData} fill={slice.color} />;
                    })}
                </svg>
                {/* Center Hole for Donut if needed, but image shows Pie */}
            </div>
        );
    };

    return (
        <div className=" bg-gray-50 py-12 px-4 sm:px-6 lg:px-8 font-sans">
            <div className="max-w-7xl mx-auto space-y-8">

                <h1 className="text-3xl font-bold text-gray-900 border-b pb-6 border-gray-200">
                    Home Loan EMI Calculator
                </h1>

                {/* Top Section: Calculator & Chart */}
                <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                    <div className="grid grid-cols-1 lg:grid-cols-12 divide-y lg:divide-y-0 lg:divide-x divide-gray-200">

                        {/* LEFT: Inputs */}
                        <div className="lg:col-span-7 p-8 space-y-10">

                            {/* Bank Select */}
                            <div>
                                <div className="relative">
                                    <select className="appearance-none w-full bg-white border border-gray-300 text-gray-700 py-3 px-4 pr-8 rounded-lg leading-tight focus:outline-none focus:bg-white focus:border-[#191758] text-sm">
                                        <option>Select Bank (Optional)</option>
                                        <option>HDFC Bank</option>
                                        <option>SBI</option>
                                        <option>ICICI Bank</option>
                                    </select>
                                    <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
                                        <ChevronDown className="h-4 w-4" />
                                    </div>
                                </div>
                            </div>

                            {/* Loan Amount */}
                            <div className="space-y-6">
                                <div className="flex justify-between items-center">
                                    <label className="text-sm font-bold text-gray-800">Loan Amount (₹)</label>
                                    <div className="bg-[#191758]/10 px-4 py-2 rounded-lg border border-[#191758]/20 text-[#191758] font-bold min-w-[120px] text-right">
                                        ₹ {loanAmount.toLocaleString('en-IN')}
                                    </div>
                                </div>
                                <div className="relative pt-1">
                                    <input
                                        type="range"
                                        min="100000"
                                        max="50000000"
                                        step="10000"
                                        value={loanAmount}
                                        onChange={(e) => setLoanAmount(Number(e.target.value))}
                                        className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-[#191758] range-slider"
                                    />
                                    <div className="flex justify-between text-xs text-gray-400 mt-2 font-medium">
                                        <span>1L</span>
                                        <span>5Cr</span>
                                    </div>
                                </div>
                            </div>

                            {/* Tenure */}
                            <div className="space-y-6">
                                <div className="flex justify-between items-center">
                                    <label className="text-sm font-bold text-gray-800">Tenure (Years)</label>
                                    <div className="bg-[#191758]/10 px-4 py-2 rounded-lg border border-[#191758]/20 text-[#191758] font-bold min-w-[80px] text-right">
                                        {tenureYears}
                                    </div>
                                </div>
                                <div className="relative pt-1">
                                    <input
                                        type="range"
                                        min="1"
                                        max="30"
                                        step="1"
                                        value={tenureYears}
                                        onChange={(e) => setTenureYears(Number(e.target.value))}
                                        className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-[#191758] range-slider"
                                    />
                                    <div className="flex justify-between text-xs text-gray-400 mt-2 font-medium">
                                        <span>1</span>
                                        <span>30</span>
                                    </div>
                                </div>
                            </div>

                            {/* Interest Rate */}
                            <div className="space-y-6">
                                <div className="flex justify-between items-center">
                                    <label className="text-sm font-bold text-gray-800">Rate of Interest (%)</label>
                                    <div className="bg-[#191758]/10 px-4 py-2 rounded-lg border border-[#191758]/20 text-[#191758] font-bold min-w-[80px] text-right">
                                        {interestRate}
                                    </div>
                                </div>
                                <div className="relative pt-1">
                                    <input
                                        type="range"
                                        min="5"
                                        max="20"
                                        step="0.1"
                                        value={interestRate}
                                        onChange={(e) => setInterestRate(Number(e.target.value))}
                                        className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-[#191758] range-slider"
                                    />
                                    <div className="flex justify-between text-xs text-gray-400 mt-2 font-medium">
                                        <span>5%</span>
                                        <span>20%</span>
                                    </div>
                                </div>
                            </div>

                            {/* Pre-payment Link */}
                            <div className="pt-2">
                                <button className="flex items-center text-[#191758] font-semibold text-sm hover:underline">
                                    <div className="border border-[#191758] rounded-sm mr-2 p-0.5">
                                        <Plus className="w-3 h-3" />
                                    </div>
                                    Add Pre-payment
                                </button>
                            </div>

                        </div>

                        {/* RIGHT: Results & Chart */}
                        <div className="lg:col-span-5 p-8 flex flex-col justify-center items-center bg-white">

                            <div className="text-center mb-8">
                                <p className="text-gray-500 font-medium text-sm mb-1">Your EMI Per Month</p>
                                <h3 className="text-3xl font-bold text-gray-900">{formatCurrency(emi)}</h3>
                            </div>

                            {/* Chart */}
                            <div className="mb-8 p-4">
                                <PieChart data={chartData} />
                            </div>

                            {/* Legend / Stats */}
                            <div className="w-full grid grid-cols-2 gap-y-6 gap-x-4">
                                <div className="space-y-1">
                                    <div className="flex items-center gap-2 text-xs text-gray-500 font-medium uppercase tracking-wide">
                                        <span className="w-3 h-3 rounded-full bg-[#B88746 ]"></span>
                                        Total Interest
                                    </div>
                                    <p className="text-lg font-bold text-gray-900 pl-5">{formatCurrency(totalInterest)}</p>
                                </div>

                                <div className="space-y-1">
                                    <div className="flex items-center gap-2 text-xs text-gray-500 font-medium uppercase tracking-wide">
                                        <span className="w-3 h-3 rounded-full bg-gray-300"></span> {/* Neutral color for fees */}
                                        Processing Fees
                                    </div>
                                    <p className="text-lg font-bold text-gray-900 pl-5">{formatCurrency(25000)}</p> {/* Hardcoded as per image example or logic */}
                                </div>

                                <div className="space-y-1">
                                    <div className="flex items-center gap-2 text-xs text-gray-500 font-medium uppercase tracking-wide">
                                        <span className="w-3 h-3 rounded-full bg-[#191758]"></span>
                                        Loan Amount
                                    </div>
                                    <p className="text-lg font-bold text-gray-900 pl-5">{formatCurrency(loanAmount)}</p>
                                </div>
                            </div>

                        </div>
                    </div>
                </div>

                {/* Bottom Section: Amortization Table */}
                <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                    <div className="p-6 border-b border-gray-200">
                        <h2 className="text-xl font-bold text-gray-900">Home Loan Amortization Table</h2>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-100 text-gray-600 font-medium">
                                <tr>
                                    <th className="px-6 py-4">Year</th>
                                    <th className="px-6 py-4 text-right">Principal (₹)</th>
                                    <th className="px-6 py-4 text-right">Interest (₹)</th>
                                    <th className="px-6 py-4 text-right">Balance (₹)</th>
                                    <th className="px-6 py-4 text-right">Paid (%)</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {amortizationSchedule.map((row, idx) => (
                                    <tr key={idx} className="hover:bg-[#191758]/5 transition-colors cursor-default even:bg-gray-50/50">
                                        <td className="px-6 py-4 font-semibold text-[#191758] underline decoration-dotted">{row.year}</td>
                                        <td className="px-6 py-4 text-right font-medium text-gray-700">{row.principal.toLocaleString('en-IN')}</td>
                                        <td className="px-6 py-4 text-right font-medium text-gray-700">{row.interest.toLocaleString('en-IN')}</td>
                                        <td className="px-6 py-4 text-right font-medium text-gray-700">{row.balance.toLocaleString('en-IN')}</td>
                                        <td className="px-6 py-4 text-right font-medium text-gray-700">{row.paidPercent}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

            </div>

            <style jsx>{`
                .range-slider::-webkit-slider-thumb {
                    -webkit-appearance: none;
                    appearance: none;
                    width: 20px;
                    height: 20px;
                    border-radius: 50%;
                    background: #191758; /* Gold */
                    cursor: pointer;
                    border: 4px solid white;
                    box-shadow: 0 0 0 2px #191758;
                }
                .range-slider::-moz-range-thumb {
                    width: 20px;
                    height: 20px;
                    border-radius: 50%;
                    background: #191758;
                    cursor: pointer;
                    border: 4px solid white;
                    box-shadow: 0 0 0 2px #191758;
                }
            `}</style>
        </div>
    );
};

export default EMIcalculator;
